import { Order } from "../domain/order";

export class OrderRepository {
  private readonly rows = new Map<string, Order>();

  insert(order: Order): void {
    if (this.rows.has(order.id)) throw new Error(`order ${order.id} already exists`);
    this.rows.set(order.id, structuredCopy(order));
  }

  update(order: Order): void {
    if (!this.rows.has(order.id)) throw new Error(`order ${order.id} not found`);
    this.rows.set(order.id, structuredCopy(order));
  }

  get(id: string): Order | undefined {
    const o = this.rows.get(id);
    return o ? structuredCopy(o) : undefined;
  }

  all(): Order[] {
    return [...this.rows.values()].map(structuredCopy);
  }
}

function structuredCopy(o: Order): Order {
  return { ...o, lines: o.lines.map((l) => ({ ...l })) };
}
import { Payment } from "../domain/payment";

/** Latest payment record per order (older attempts are kept for audit only). */
export class PaymentRepository {
  private readonly history: Payment[] = [];

  record(p: Payment): void {
    this.history.push({ ...p });
  }

  latestFor(orderId: string): Payment | undefined {
    let latest: Payment | undefined;
    for (const p of this.history) {
      if (p.orderId !== orderId) continue;
      if (!latest || p.updatedAt >= latest.updatedAt) latest = p;
    }
    return latest ? { ...latest } : undefined;
  }

  attempts(orderId: string): number {
    return this.history.filter((p) => p.orderId === orderId).length;
  }
}
import { Shipment } from "../domain/shipment";

export class ShipmentRepository {
  private readonly byOrder = new Map<string, Shipment>();

  upsert(s: Shipment): void {
    const prev = this.byOrder.get(s.orderId);
    if (prev && prev.updatedAt > s.updatedAt) return; // out-of-order carrier webhook
    this.byOrder.set(s.orderId, { ...s });
  }

  get(orderId: string): Shipment | undefined {
    const s = this.byOrder.get(orderId);
    return s ? { ...s } : undefined;
  }
}
export enum PaymentStatus {
  Pending = "PENDING",
  Authorized = "AUTHORIZED",
  Captured = "CAPTURED",
  Failed = "FAILED",
  Refunded = "REFUNDED",
}

export interface Payment {
  orderId: string;
  status: PaymentStatus;
  amount: number;
  method: "card" | "transfer" | "points";
  updatedAt: number;
}

export function isPaymentStatus(s: string): s is PaymentStatus {
  return (Object.values(PaymentStatus) as string[]).includes(s);
}
export enum ShipmentStatus {
  Ready = "READY",
  InTransit = "IN_TRANSIT",
  Delivered = "DELIVERED",
  Failed = "FAILED",
  Returned = "RETURNED",
}

export interface Shipment {
  orderId: string;
  status: ShipmentStatus;
  carrier: string;
  trackingNo?: string;
  updatedAt: number;
}

export function isShipmentStatus(s: string): s is ShipmentStatus {
  return (Object.values(ShipmentStatus) as string[]).includes(s);
}
export interface Page<T> {
  items: T[];
  page: number;
  pageSize: number;
  total: number;
  hasNext: boolean;
}

export function paginate<T>(all: T[], page: number, pageSize: number): Page<T> {
  const size = Math.max(1, Math.floor(pageSize));
  const p = Math.max(1, Math.floor(page));
  const start = (p - 1) * size;
  const items = all.slice(start, start + size);
  return { items, page: p, pageSize: size, total: all.length, hasNext: start + size < all.length };
}

/** Stable multi-key sort. Each key returns a number or string; ties fall through to the next key. */
export function sortBy<T>(items: T[], ...keys: ((t: T) => number | string)[]): T[] {
  return items
    .map((item, index) => ({ item, index }))
    .sort((a, b) => {
      for (const key of keys) {
        const ka = key(a.item);
        const kb = key(b.item);
        if (ka < kb) return -1;
        if (ka > kb) return 1;
      }
      return a.index - b.index;
    })
    .map((x) => x.item);
}

